mapper.select:
SELECT o.id, o.customer_name AS customer, o.phone, pkg.name AS pkgName, o.amount, o.sales_name AS sales, o.community_name AS community, o.order_type AS orderType, o.status, DATE_FORMAT(FROM_UNIXTIME(o.created_time/1000), '%Y-%m-%d %H:%i') AS time FROM biz_order o LEFT JOIN package_info pkg ON pkg.id = o.package_id WHERE 1 = 1
AND o.dept_id IN #{d}
AND o.status = #{status}
AND (o.id LIKE CONCAT('%',#{keyword},'%') OR o.customer_name LIKE CONCAT('%',#{keyword},'%') OR o.phone LIKE CONCAT('%',#{keyword},'%'))
ORDER BY o.created_time DESC LIMIT 500
